import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync,existsSync} from 'node:fs';
const m = await import('../model.mjs').catch(()=>({}));
test('same-phase sources construct fully on the bisector',()=>{assert.equal(typeof m.sampleField,'function');for(const z of [0,.5,2,3])assert.ok(Math.abs(m.sampleField(0,z,{frequency:220,separation:2.4,phase:0}).intensity-1)<1e-12)});
test('opposite-phase equal paths cancel, including the center',()=>{for(const z of [0,.5,2,3])assert.ok(m.sampleField(0,z,{frequency:220,separation:2.4,phase:180}).intensity<1e-28)});
test('half wavelength path difference cancels at equal gain; full wavelength reinforces',()=>{assert.ok(m.interference(1,1,Math.PI).intensity<1e-28);assert.ok(Math.abs(m.interference(1,1,2*Math.PI).intensity-1)<1e-12)});
test('phase wraps and mirror symmetry is physically preserved',()=>{const a=m.sampleField(1.4,.8,{frequency:320,separation:2.4,phase:45});const b=m.sampleField(-1.4,.8,{frequency:320,separation:2.4,phase:315});assert.ok(Math.abs(a.intensity-b.intensity)<1e-12);assert.deepEqual(m.sanitize({phase:720}),m.sanitize({phase:0}))});
test('all UI bounds and source locations produce finite normalized values',()=>{for(const frequency of [140,220,440,520])for(const separation of [.8,2.4,3.6])for(const phase of [0,90,180,270,360])for(const x of [-4,-separation/2,0,separation/2,4])for(const z of [-3,0,3]){const r=m.sampleField(x,z,{frequency,separation,phase});assert.ok(Object.values(r).every(Number.isFinite));assert.ok(r.intensity>=0&&r.intensity<=1);assert.ok(r.decibels<=0&&r.decibels>=-80)}});
test('invalid controls are clamped and nan gets safe defaults',()=>{assert.equal(m.sanitize({frequency:NaN}).frequency,220);assert.equal(m.sanitize({frequency:10000,separation:-10}).frequency,520);assert.equal(m.sanitize({separation:-10}).separation,.8)});
test('frequency controls wavelength and changes off-axis pattern',()=>{assert.equal(m.wavelength(343),1);assert.notEqual(m.sampleField(1,1,{frequency:220}).intensity,m.sampleField(1,1,{frequency:440}).intensity)});
test('UI exposes keyboard controls, opt-in sound, pause and real Three.js',()=>{assert.ok(existsSync(new URL('../index.html',import.meta.url)));const h=readFileSync(new URL('../index.html',import.meta.url),'utf8');for(const id of ['frequency','separation','phase','audio','pause','reset','probe-x','probe-z'])assert.ok(h.includes('id="'+id+'"'));const a=readFileSync(new URL('../app.mjs',import.meta.url),'utf8');assert.match(a,/vendor\/three.module.min.js/);assert.match(a,/THREE.WebGLRenderer/);assert.match(a,/THREE.Raycaster/);assert.match(a,/webglcontextlost/)});
test('a real Three.js SVG 3D fallback remains available without WebGL',()=>{const a=readFileSync(new URL('../app.mjs',import.meta.url),'utf8');assert.match(a,/new SVGRenderer/);assert.match(a,/SVG 3D/);assert.match(a,/THREE.MeshLambertMaterial/);const v=readFileSync(new URL('../vendor/SVGRenderer.js',import.meta.url),'utf8');assert.match(v,/from '.\/three.module.min.js'/);assert.doesNotMatch(v,/from 'three'/)});
test('picked probe precision reproduces the visible coordinates exactly',()=>{assert.equal(typeof m.snapProbe,'function');assert.deepEqual(m.snapProbe(-.26,.54),{x:-.3,z:.5});assert.deepEqual(m.snapProbe(50,-50),{x:4,z:-3});const p=m.snapProbe(-.26,.54);assert.equal(m.sampleField(p.x,p.z,{frequency:520,phase:180}).intensity,m.sampleField(Number(p.x.toFixed(1)),Number(p.z.toFixed(1)),{frequency:520,phase:180}).intensity)});
test('crest rings share real wavelength spacing and positive B-leading direction',()=>{assert.equal(typeof m.ringRadius,'function');const p={frequency:220,phase:180};assert.ok(Math.abs(m.ringRadius(.1,1,0,p)-m.ringRadius(.1,0,0,p)-343/220)<1e-12);assert.ok(Math.abs(m.ringRadius(0,0,1,p)-m.ringRadius(0,0,0,p)-343/220/2)<1e-12);assert.ok(m.ringRadius(0,1,0,{frequency:440})<m.ringRadius(0,1,0,{frequency:220}))});
test('numerical probe output has a polite live announcement',()=>{const h=readFileSync(new URL('../index.html',import.meta.url),'utf8');assert.match(h,/id="accessible-reading"[^>]*role="status"[^>]*aria-live="polite"/);});
test('camera framing backs away on narrow viewports',()=>{assert.equal(typeof m.viewDistance,'function');assert.equal(m.viewDistance(1.4),14.8);assert.ok(m.viewDistance(.75)>m.viewDistance(1.4));assert.ok(Number.isFinite(m.viewDistance(0)))});
